package ai.nexusone.controller;
import ai.nexusone.dto.*; import ai.nexusone.enums.*; import ai.nexusone.service.*; import jakarta.validation.Valid; import java.util.Map; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/autonomous-enterprise-reasoning") @CrossOrigin(origins="http://localhost:5173") public class AutonomousEnterpriseReasoningController{private final AutonomousEnterpriseReasoningService service;public AutonomousEnterpriseReasoningController(AutonomousEnterpriseReasoningService s){service=s;} @PostMapping("/generate") ResponseEntity<AutonomousEnterpriseReasoningResponse> generate(@Valid @RequestBody AutonomousEnterpriseReasoningRequest q){return ResponseEntity.status(HttpStatus.CREATED).body(service.generate(q));} @GetMapping("/{id}") AutonomousEnterpriseReasoningResponse get(@PathVariable Long id){return service.get(id);} @GetMapping("/history") Page<AutonomousEnterpriseReasoningResponse> history(@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return service.history(p);} @GetMapping("/search") Page<AutonomousEnterpriseReasoningResponse> search(@RequestParam(required=false)String keyword,@RequestParam(required=false)AutonomousEnterpriseReasoningPriority priority,@RequestParam(required=false)AutonomousEnterpriseReasoningStatus status,@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return service.search(keyword,priority,status,p);} @PostMapping("/{id}/review") AutonomousEnterpriseReasoningResponse review(@PathVariable Long id,@Valid @RequestBody AutonomousEnterpriseReasoningActionRequest q){return service.review(id,q);} @PostMapping("/{id}/approve") AutonomousEnterpriseReasoningResponse approve(@PathVariable Long id,@Valid @RequestBody AutonomousEnterpriseReasoningActionRequest q){return service.approve(id,q);} @PostMapping("/{id}/reject") AutonomousEnterpriseReasoningResponse reject(@PathVariable Long id,@Valid @RequestBody AutonomousEnterpriseReasoningActionRequest q){return service.reject(id,q);} @PostMapping("/{id}/publish") AutonomousEnterpriseReasoningResponse publish(@PathVariable Long id,@Valid @RequestBody AutonomousEnterpriseReasoningActionRequest q){return service.publish(id,q);} @GetMapping({"/analytics","/dashboard"}) AutonomousEnterpriseReasoningAnalyticsResponse analytics(){return service.analytics();} @GetMapping("/health") Map<String,String> health(){return Map.of("status","UP","mode","AUTONOMOUS_ENTERPRISE_REASONING_ENGINE");}}
